"""Value semantics for minisql.

All operators and functions here work on already-evaluated values.  A value
is one of ``None`` (SQL NULL), ``bool``, ``int``, ``float``, or ``str``.
Booleans are never treated as numbers, even though ``bool`` is a subclass of
``int`` in Python.
"""

import re
from decimal import Decimal, DecimalException, ROUND_HALF_UP, localcontext

from .errors import QueryError


_OPERATORS = frozenset(("+", "-", "*", "/", "||"))

_SCALAR_ARITY = {
    "lower": 1,
    "upper": 1,
    "length": 1,
    "abs": 1,
    "round": (1, 2),
    "coalesce": None,  # at least one argument
}

_AGGREGATES = frozenset(("count", "sum", "avg", "min", "max"))


def is_number(value):
    """Return True for int/float values, but not bool (or NULL)."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _type_name(value):
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "number"
    if isinstance(value, str):
        return "text"
    return type(value).__name__


def _require_number(value, what):
    if not is_number(value):
        raise QueryError(
            "%s requires a number, got %s" % (what, _type_name(value))
        )


def _require_text(value, what):
    if not isinstance(value, str):
        raise QueryError(
            "%s requires text, got %s" % (what, _type_name(value))
        )


def binary_op(op, left, right):
    """Apply a binary SQL operator to two values.

    ``op`` is one of ``+ - * / ||``.  NULL propagates through every operator.
    """
    if op not in _OPERATORS:
        raise QueryError("unknown operator: %s" % (op,))
    if left is None or right is None:
        return None

    if op == "||":
        return to_text(left) + to_text(right)

    _require_number(left, "operator %s" % op)
    _require_number(right, "operator %s" % op)

    try:
        if op == "+":
            result = left + right
        elif op == "-":
            result = left - right
        elif op == "*":
            result = left * right
        else:  # "/"
            if right == 0:
                return None
            return float(left) / float(right)

        if isinstance(left, int) and isinstance(right, int):
            return int(result)
        return float(result)
    except (OverflowError, ValueError) as exc:
        raise QueryError("arithmetic error: %s" % (exc,))


def compare(left, right):
    """Compare two values, returning -1, 0, 1, or None for NULL.

    Numbers compare numerically, booleans with booleans, and strings by code
    point.  Comparing different categories is an error.
    """
    if left is None or right is None:
        return None

    left_number = is_number(left)
    right_number = is_number(right)

    if left_number and right_number:
        if left < right:
            return -1
        if left > right:
            return 1
        return 0

    if isinstance(left, bool) and isinstance(right, bool):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0

    if isinstance(left, str) and isinstance(right, str):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0

    raise QueryError(
        "cannot compare %s with %s" % (_type_name(left), _type_name(right))
    )


def _require_bool(value, what):
    if value is not None and not isinstance(value, bool):
        raise QueryError(
            "%s requires a boolean, got %s" % (what, _type_name(value))
        )


def sql_and(a, b):
    """Three-valued SQL AND."""
    _require_bool(a, "AND")
    _require_bool(b, "AND")
    if a is False or b is False:
        return False
    if a is True and b is True:
        return True
    return None


def sql_or(a, b):
    """Three-valued SQL OR."""
    _require_bool(a, "OR")
    _require_bool(b, "OR")
    if a is True or b is True:
        return True
    if a is False and b is False:
        return False
    return None


def sql_not(a):
    """Three-valued SQL NOT."""
    _require_bool(a, "NOT")
    if a is None:
        return None
    return not a


def _like_regex(pattern):
    parts = []
    for char in pattern:
        if char == "%":
            parts.append(".*")
        elif char == "_":
            parts.append(".")
        else:
            parts.append(re.escape(char))
    return "".join(parts)


def like(value, pattern):
    """Whole-string, case-sensitive SQL LIKE."""
    if value is None or pattern is None:
        return None
    _require_text(value, "LIKE")
    _require_text(pattern, "LIKE")
    return re.fullmatch(_like_regex(pattern), value, re.DOTALL) is not None


def to_text(value):
    """Convert a scalar value to its SQL text representation."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, str):
        return value
    if is_number(value):
        return str(value)
    raise QueryError("cannot convert %s to text" % (_type_name(value),))


def _check_arity(name, args):
    arity = _SCALAR_ARITY.get(name)
    if arity is None:
        # coalesce: any positive number of arguments
        if not args:
            raise QueryError("%s requires at least 1 argument" % name.upper())
        return

    if isinstance(arity, tuple):
        low, high = arity
    else:
        low = high = arity

    if not (low <= len(args) <= high):
        if low == high:
            expected = "%d argument%s" % (low, "" if low == 1 else "s")
        else:
            expected = "%d or %d arguments" % (low, high)
        raise QueryError(
            "%s requires %s, got %d" % (name.upper(), expected, len(args))
        )


def _decimal_places(value):
    """Digits after the decimal point in Decimal's representation."""
    exponent = value.as_tuple().exponent
    return max(0, -exponent)


def _round_value(x, places):
    """Round half away from zero, using Decimal for exact decimal input."""
    _require_number(x, "ROUND")
    try:
        decimal_value = Decimal(str(x))
    except (DecimalException, ValueError, TypeError) as exc:
        raise QueryError("ROUND: %s" % (exc,))

    if not decimal_value.is_finite():
        raise QueryError("ROUND requires a finite number")

    digits = len(decimal_value.as_tuple().digits)
    if places is None:
        # Convert to an integer.
        try:
            with localcontext() as context:
                context.prec = max(
                    28, digits + 5, decimal_value.adjusted() + 5
                )
                rounded = decimal_value.quantize(
                    Decimal(1), rounding=ROUND_HALF_UP
                )
            return int(rounded)
        except (DecimalException, ValueError, OverflowError) as exc:
            raise QueryError("ROUND: %s" % (exc,))

    # A huge positive number of places cannot change the value.
    if places >= _decimal_places(decimal_value):
        return float(decimal_value)

    # Rounding to a power of ten far above the value gives zero.
    if places < 0 and -places > decimal_value.adjusted() + 1:
        return 0.0

    try:
        with localcontext() as context:
            context.prec = max(
                28, digits + 5, decimal_value.adjusted() + 5
            )
            quantum = Decimal(1).scaleb(-places)
            rounded = decimal_value.quantize(
                quantum, rounding=ROUND_HALF_UP
            )
        return float(rounded)
    except (DecimalException, ValueError, OverflowError) as exc:
        raise QueryError("ROUND: %s" % (exc,))


def scalar_function(name, args):
    """Evaluate a scalar SQL function over already-evaluated arguments."""
    if not isinstance(name, str):
        raise QueryError("invalid function name")
    name = name.lower()

    # Validate the function and its arity before doing anything else.
    _check_arity(name, args)

    # COALESCE is the only scalar function that does not propagate NULLs.
    if name == "coalesce":
        for arg in args:
            if arg is not None:
                return arg
        return None

    # NULL propagates through every other scalar function.
    if any(arg is None for arg in args):
        return None

    if name in ("lower", "upper", "length"):
        text = args[0]
        _require_text(text, name.upper())
        if name == "lower":
            return text.lower()
        if name == "upper":
            return text.upper()
        return len(text)

    if name == "abs":
        value = args[0]
        _require_number(value, "ABS")
        return abs(value)

    if name == "round":
        x = args[0]
        places = args[1] if len(args) == 2 else None
        if places is not None and (
            not isinstance(places, int) or isinstance(places, bool)
        ):
            raise QueryError(
                "ROUND requires an integer number of places, got %s"
                % (_type_name(places),)
            )
        return _round_value(x, places)

    # Unreachable: _check_arity only accepts the names above.
    raise QueryError("unknown function: %s" % (name.upper(),))


def aggregate(name, values):
    """Evaluate an aggregate over the values of one group."""
    if not isinstance(name, str):
        raise QueryError("invalid aggregate name")
    name = name.lower()
    if name not in _AGGREGATES:
        raise QueryError("unknown aggregate: %s" % (name.upper(),))

    present = [value for value in values if value is not None]

    if name == "count":
        return len(present)

    if not present:
        return None

    if name in ("sum", "avg"):
        for value in present:
            _require_number(value, name.upper())

    if name == "sum":
        total = 0
        for value in present:
            total += value
        if all(isinstance(value, int) for value in present):
            return int(total)
        try:
            return float(total)
        except (OverflowError, ValueError) as exc:
            raise QueryError("SUM: %s" % (exc,))

    if name == "avg":
        total = 0
        for value in present:
            total += value
        try:
            return float(total) / len(present)
        except (OverflowError, ValueError) as exc:
            raise QueryError("AVG: %s" % (exc,))

    # MIN / MAX: use compare so incompatible types raise QueryError.
    best = present[0]
    for value in present[1:]:
        ordering = compare(value, best)
        if (name == "min" and ordering < 0) or (
            name == "max" and ordering > 0
        ):
            best = value
    return best

